      "nextPomodoroText": {
        "type": "string",
        "description": "下一段番茄钟状态文本",
        "sampleValue": "25:00"
      },
      "subjects": {
        "type": "array",
        "description": "横向科目复习列表",
        "sampleValue": [
          {
            "name": "综合",
            "timerText": "25:00",
            "mark": "01"
          },
          {
            "name": "法规",
            "timerText": "18:30",
            "mark": "02"
