            "mark": "03"
          },
          {
            "name": "案例",
            "timerText": "12:10",
            "mark": "04"
          }
        ],
        "items": {
          "type": "object",
          "description": "单个科目的复习倒计时信息",
          "properties": {
            "name": {
              "type": "string",
              "description": "科目名称",
              "sampleValue": "综合"
            },
            "timerText": {
              "type": "string",
              "description": "该科目的番茄钟倒计时文本",
              "sampleValue": "25:00"
            },
            "mark": {
              "type": "string",
              "description": "用文字符号表示的科目标记",
              "sampleValue": "01"
            }
          }
        }
      }
    }
  },
  "assetCandidates": []
}

